import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>图片是大多数网站最重的部分。页面加载慢，通常都是图片的问题，而修复它们是最快的速度提升方法。</p>\n<p>这篇指南会走完整个优化流程。你会检查页面、选对预设、优化图片，再把HTML代码粘贴到位。</p>\n<p>它适用于博客、网店和企业网站，除了复制粘贴，不需要任何编程经验。</p>\n<h2 id=\"audit-first\">第一步：先检查页面</h2>\n<p>优化任何东西之前，先找出哪些图片是问题。打开页面，留意哪些图片出现得很慢。</p>\n<p>用免费的速度工具测量页面。它会列出最重的图片，显示每张图片在加载时间上花了多少成本。</p>\n<p>记下页面的图片总重量。图片总共5MB的页面明显有问题，500KB的页面已经状态不错了。</p>\n<p>写下最糟糕的三张图片。先修复它们，花最少的力气就能得到最大的速度提升。</p>\n<h2 id=\"step-2-open\">第二步：打开网页图片优化工具</h2>\n<p>在浏览器里打开<a href=\"/zh/wangye-tupian-youhua/\">网页图片优化工具</a>。不需要账号，也不用安装。</p>\n<p>工具完全在你的设备上运行。图片在本地处理，永远不会上传到服务器。</p>\n<p>优化整个网站时，分批处理。一次三十张图片，对大多数浏览器来说是很舒服的批量大小。</p>\n<p>把页面加入收藏。图片优化是经常要做的工作，这个工具你会一次次回来用。</p>\n<h2 id=\"step-3-preset\">第三步：选对预设</h2>\n<p>按图片将要出现的位置选择预设。首图、商品照和缩略图各有自己的预设。</p>\n<p>电商商品预设是默认的。它把图片上限设为1200像素宽，WebP格式，82%的画质，适合大多数商品照片。</p>\n<p>博客头图按版式用首图或卡片预设。预设要按显示尺寸来配，而不是按文件大小来配。</p>\n<p>社交分享图片用社交OG预设。它会自动切换到JPG格式，因为社交平台更喜欢JPG。</p>\n<h2 id=\"step-4-upload\">第四步：上传图片</h2>\n<p>把图片拖到上传区域，或者点一下浏览选择。支持JPG、PNG、WebP和HEIC文件。</p>\n<p>上传你手里画质最高的原图。1200万像素的原图能给优化工具留出大得多的发挥空间，小副本就不行。</p>\n<p>批量处理时，把一个页面的图片一次性全加进来。它们共享同一个预设，结果保持一致。</p>\n<p>改设置之前，等上传完成。工具需要拿到完整的文件，才能优化它们。</p>\n<h2 id=\"step-5-customise\">第五步：自定义设置</h2>\n<p>选好预设后，如果位置有要求，再调整设置。按设计改尺寸、格式或画质。</p>\n<p>尺寸尽量接近显示尺寸。显示800像素宽的图片，文件里没必要做到2400像素。</p>\n<p>批量里大小图片混杂时，打开“仅缩小”。它能保护图标和缩略图不被拉大。</p>\n<p>只有必要时才动画质滑块。大多数预设在75%到85%之间，这个范围对几乎每张图片都合适。</p>\n<h2 id=\"step-6-preview\">第六步：预览结果</h2>\n<p>下载之前，用全尺寸预览每张优化后的图片。小缩略图会藏住问题，全尺寸下一眼就能看出来。</p>\n<p>先看细腻的细节。布料纹理、文字和边缘是最先在压缩下变柔和的地方。</p>\n<p>拿几张结果和原图对比一下。细微的差别很正常，读不懂的文字或斑驳的皮肤就不正常。</p>\n<p>文件大小也要看。汇总会显示每张图片缩小了多少，以及整批总共省了多少。</p>\n<h2 id=\"step-7-copy-html\">第七步：复制HTML标签</h2>\n<p>每张图片点“复制图片标签”。标签里包括图片来源、尺寸、替代文字和加载行为，可以直接粘贴。</p>\n<p>检查标签里的替代文字。生成的文字描述得不好时，编辑一下。</p>\n<p>确认加载属性对不对。首图应该立刻加载，首屏以下的图片应该懒加载。</p>\n<p>把标签粘贴到页面里图片所属的位置。完整替换旧的图片标签，而不是手动编辑它。</p>\n<h2 id=\"step-8-upload\">第八步：上传并测试页面</h2>\n<p>把优化好的图片上传到网站。用工具生成的文件名，让HTML标签和文件对应起来。</p>\n<p>在新的浏览器标签页里打开页面。检查每张图片都出现了，没有拉伸或模糊的地方。</p>\n<p>再运行一次速度工具，对比数字。图片总重量应该大幅下降，加载时间也跟着下降。</p>\n<p>手机上也要测试。大多数访客用手机浏览，页面首先要在手机上感觉快。</p>\n<h2 id=\"fixing-problems\">常见问题的修复方法</h2>\n<p>图片看起来模糊，可能是原图本身就太小了。用同一个预设，从更大的原图重新优化。</p>\n<p>页面还是加载很慢，检查有没有漏掉的未优化图片。一张被遗忘的5MB横幅就能毁掉整批的努力。</p>\n<p>图片显示拉伸了，说明标签里的尺寸和文件不匹配。从工具里重新复制标签，不要手动编辑它。</p>\n<p>社交分享没有显示图片，检查格式。社交平台更喜欢JPG，社交OG预设会自动处理这一点。</p>\n<h2 id=\"blog-workflow\">实战：一篇博客文章</h2>\n<p>把文章的图片收集起来，一次性批量上传。缩略图用卡片预设，头图用首图预设。</p>\n<p>仔细预览头图。它是页面上最大的图片，也是读者最先评判的那一张。</p>\n<p>复制HTML标签，粘贴到文章里。发布之前，检查每个标签的替代文字。</p>\n<p>发布文章，在手机上测试。滚动浏览时，图片应该加载很快、看起来锐利。</p>\n<h2 id=\"shop-workflow\">实战：商品页面</h2>\n<p>把商品照片收集起来，一次性批量上传。用电商商品预设，结果最一致。</p>\n<p>先预览细节最多的商品。布料纹理和印刷标签是最先变柔和的地方。</p>\n<p>复制HTML标签，粘贴到商品页面。确认每张图片位置的加载属性都正确。</p>\n<p>上传后在手机上检查商品页面。大多数顾客用手机浏览，图片必须在手机上好看。</p>\n<h2 id=\"speed-tools\">用好免费的速度工具</h2>\n<p>免费的速度工具会测量你的页面并列出问题。它们是任何优化工作的最佳起点。</p>\n<p>在上线页面上运行工具，不要在本地副本上跑。上线页面包括托管、CDN和访客面对的真实条件。</p>\n<p>先读图片相关的建议。它们会点名哪些文件最花时间，告诉你从哪里开始。</p>\n<p>不要追求满分。分数落在绿色区间就够好了，追100分是浪费时间，不如把时间花在内容上。</p>\n<p>每轮修复之后重新运行工具。变化的数字能告诉你，工作有没有见效。</p>\n<h2 id=\"image-sizes-by-slot\">按页面位置选尺寸</h2>\n<p>页面上每个位置都有自然的图片尺寸。文件和位置匹配，是网页优化的核心技能。</p>\n<p>首图需要最大的文件，常常1200到1600像素宽。它们铺满屏幕，所以必须保持锐利。</p>\n<p>博客文章里的头图适合800到1200像素。它们很大，但不是全屏，中间尺寸正好。</p>\n<p>缩略图和头像只需要200到400像素。再大就是浪费带宽，细节根本没人看得见。</p>\n<p>选择之前，先测量主题里的位置。显示宽度决定了文件宽度，猜错了会浪费KB。</p>\n<h2 id=\"srcset-basics\">响应式图片的实际做法</h2>\n<p>响应式图片会给不同的屏幕提供不同的文件。手机拿到小文件，桌面拿到大文件。</p>\n<p>srcset属性列出可用的尺寸，浏览器会为它运行的屏幕挑选合适的那一个。</p>\n<p>每张图片生成两到三个尺寸。手机尺寸、平板尺寸和桌面尺寸，几乎能覆盖所有访客。</p>\n<p>加上响应式图片后，在真实的手机上测试。手机上的加载改善常常非常明显。</p>\n<p>HTML保持简单。三个尺寸的srcset完全够用，十个尺寸只会增加复杂性，看不见好处。</p>\n<h2 id=\"image-seo\">优化时的图片SEO</h2>\n<p>优化和SEO是一回事。又快、图片描述又清楚的页面，比又慢、文件匿名的页面排名更好。</p>\n<p>用描述性的文件名。blue-cotton-shirt.jpg这样的名字，能告诉搜索引擎图片里是什么。</p>\n<p>每张图片写真实的替代文字。用一句话描述内容，带上搜索者会找的关键细节。</p>\n<p>不要在文件名或替代文字里堆关键词。自然的描述对读者和搜索引擎都有帮助。</p>\n<p>网站依赖图片搜索时，提交图片站点地图。它能帮搜索引擎发现那些可能错过的图片。</p>\n<h2 id=\"maintenance\">长期维护优化过的图片</h2>\n<p>优化不是一次性的工作。每周都有新图片到来，每张都需要和上一张同样的处理。</p>\n<p>把优化放进发布检查清单。每篇文章上线之前，都要经过优化工具。</p>\n<p>每个季度检查一次网站。优化习惯养成之前的旧图片常常依然很重，一批处理就能快速修复。</p>\n<p>留意主题变化。新主题显示图片的尺寸可能比旧主题大，旧文件突然就太小了。</p>\n<p>原图保存好。设计变了，原图能让你按新的尺寸重新优化，不损失画质。</p>\n<h2 id=\"team-optimisation\">团队的优化标准</h2>\n<p>一起发布内容的团队需要一个共同标准。第一篇文章之前，就约定好预设、命名格式和尺寸预算。</p>\n<p>把标准写在一页纸上。团队维基里的一份简短指南，能省掉上百个小问题。</p>\n<p>每次发布指定一个人检查图片重量。第二双眼睛能发现作者漏掉的沉重图片。</p>\n<p>设计变了就检查标准。适合去年主题的预设，不一定适合今年的版式。</p>\n<p>好的标准能让速度变成常规。团队不再为优化操心，因为流程会自动处理它。</p>\n<h2 id=\"common-speed-myths\">值得忽略的速度误区</h2>\n<p>一个误区说只有首页的速度重要。实际上，访客会落在博客文章和商品页面上，那些页面也必须快。</p>\n<p>另一个误区说快速的主机能修复慢图片。主机有帮助，但5MB的图片在任何主机上都很慢，优化才是唯一的修复方法。</p>\n<p>第三个误区说只用WebP就能解决一切。格式有帮助，但尺寸和懒加载和格式选择一样重要。</p>\n<p>真相很无聊、也很实际：尺寸对、格式对、首屏以下懒加载、每个标签里都有尺寸。做好这四件事，页面就会快。</p>\n<p>用自己的页面测试来解决问题。速度数字不在乎误区，它们会告诉你什么真正有效。</p>\n<h2 id=\"final-check-speed\">发布前的最后检查</h2>\n<p>所有图片优化完后，最后再运行一次速度工具。确认图片总重量下降了，加载时间改善了。</p>\n<p>用真实的手机、走移动网络加载页面。实验室测试里的数字有用，但手机上的感觉才是真相。</p>\n<p>每张图片再看一次。首图模糊的快速页面不是成功，仔细预览能发现它。</p>\n<h2 id=\"keep-learning\">从每个页面继续学习</h2>\n<p>你优化的每个页面都能教会你一些东西。记下哪个预设管用、哪张图片最难、速度数字发生了什么变化，因为这些教训会随着你修复的每个页面、改善的每个网站不断累积。</p>\n<p>这些笔记成了你的操作手册。下个页面花的时间更少，因为上个页面已经回答了那些问题。</p>\n<p>想看优化工具的完整指南，可以读<a href=\"/zh/blog/wang-ye-tu-pian-you-hua-qi-wan-zheng-zhi-nan/\">网页图片优化工具：完整指南</a>。想深入了解核心网页指标，可以看<a href=\"/zh/blog/tu-pian-you-hua-he-xin-wang-ye-zhi-biao-lcp-yu-wen-jian-da-xiao/\">图片优化与核心网页指标：LCP与文件大小</a>。只需要简单的大小目标时，<a href=\"/zh/tupian-yasuo-dao-200kb/\">200KB压缩工具</a>能覆盖大多数网页图片。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"优化图片后，网站能快多少？","answer":"要看图片原来有多重。图片总共5MB的页面降到500KB，加载能快好几秒，手机上尤其明显。优化前后各跑一次速度测试，就能看到你的页面精确的改善。"},{"question":"应该先优化图片再上传，还是先上传再优化？","answer":"先优化再上传。先优化能控制尺寸、格式和画质，还能拿到现成的HTML标签。先上传、指望平台压缩，通常结果更差。"},{"question":"能一次优化三十张博客图片吗？","answer":"可以。一次加入三十张图片，选一个预设，一起下载。下载整批之前，先预览几张结果，预设保持一致，网站上的图片看起来才统一。"},{"question":"首图优化后还是很慢，为什么？","answer":"检查首图的懒加载是不是关掉了，推迟首图会伤害加载速度。再确认首图尺寸和显示尺寸匹配，过大的首图会浪费带宽。预加载首图能进一步改善。"},{"question":"替换图片时需要更新HTML吗？","answer":"需要，如果尺寸或文件名变了。HTML标签里带有宽度、高度和来源，过时的标签会拉伸图片或弄坏版式。每次替换图片，都从工具里复制一个新的标签。"},{"question":"博客头图应该用多大的图片？","answer":"按主题的显示尺寸来，通常1200像素宽或更小。首图或卡片预设会自动处理这一点。图片做成显示宽度的两倍，只会浪费带宽，看不见好处。"}];
